"""Implement fixed-size and structure-aware chunking."""
import re
import uuid
from typing import Iterator

from .models import Chunk, DocumentPage

# Stable namespace for all chunk IDs generated by this module. Changing it
# changes every ID, so keep it fixed for the lifetime of a collection.
_CHUNK_NAMESPACE = uuid.UUID("0d8b5c1e-6a1f-5f65-9f4e-2b7c3a9d1e60")

# A paragraph is a run of non-empty lines; a blank line ends the paragraph.
_PARAGRAPH_RE = re.compile(r"[^\n]+(?:\n(?!\n)[^\n]+)*")
# Sentence boundary used when an oversized paragraph has to be split.
_SENTENCE_END_RE = re.compile(r"[.!?…](?=\s|$)")


def _trimmed_span(text: str, start: int, end: int) -> tuple[int, int] | None:
    """Shrink ``[start, end)`` to its non-whitespace content."""
    while start < end and text[start].isspace():
        start += 1
    while end > start and text[end - 1].isspace():
        end -= 1
    if start >= end:
        return None
    return start, end


def _chunk_id(page: DocumentPage, strategy: str, index: int,
              start: int, end: int, text: str) -> str:
    """Build a stable, Qdrant-compatible ID for one chunk."""
    key = "\x1f".join(
        (
            str(page.document_id),
            str(page.page),
            strategy,
            str(index),
            str(start),
            str(end),
            text,
        )
    )
    return str(uuid.uuid5(_CHUNK_NAMESPACE, key))


def _make_chunk(page: DocumentPage, strategy: str, index: int,
                start: int, end: int, extra: dict | None = None,
                text_override: str | None = None) -> Chunk:
    text = page.text[start:end] if text_override is None else text_override
    metadata = dict(page.metadata)
    metadata.update(
        {
            "chunk_strategy": strategy,
            "chunk_index": index,
            "char_start": start,
            "char_end": end,
            "char_count": len(text),
            # Human-readable key kept in the payload for easier debugging.
            "chunk_key": f"{page.document_id}:p{page.page}:{strategy}:{index:04d}",
        }
    )
    if extra:
        metadata.update(extra)
    return Chunk(
        chunk_id=_chunk_id(page, strategy, index, start, end, text),
        document_id=page.document_id,
        source=page.source,
        page=page.page,
        text=text,
        metadata=metadata,
    )


def _window_spans(text: str, size: int, overlap: int) -> Iterator[tuple[int, int]]:
    """Yield character windows, trimming whitespace without moving the stride."""
    step = size - overlap
    text_length = len(text)
    start = 0
    while start < text_length:
        raw_end = min(start + size, text_length)
        span = _trimmed_span(text, start, raw_end)
        if span is not None:
            yield span
        if raw_end >= text_length:
            break
        start += step


def fixed_size(page: DocumentPage, size: int, overlap: int) -> list[Chunk]:
    """Split text into overlapping character windows and retain page metadata.

    ``size`` is measured in Unicode characters and ``overlap`` must be smaller
    than ``size``; a stride of ``size - overlap`` is used. Empty or
    whitespace-only pages produce no chunks.
    """
    if size <= 0:
        raise ValueError("size must be greater than 0")
    if overlap < 0:
        raise ValueError("overlap must be >= 0")
    if overlap >= size:
        raise ValueError("overlap must be smaller than size")

    text = page.text or ""
    if not text.strip():
        return []

    return [
        _make_chunk(
            page,
            "fixed",
            index,
            start,
            end,
            {"chunk_size_limit": size, "chunk_overlap": overlap},
        )
        for index, (start, end) in enumerate(_window_spans(text, size, overlap))
    ]


def _best_cut(window: str, max_size: int) -> int:
    """Choose a cut position near the end of ``window`` (<= ``max_size``)."""
    # Prefer a sentence boundary in the second half of the window.
    best = -1
    for match in _SENTENCE_END_RE.finditer(window):
        if match.end() <= max_size and match.end() >= max_size // 2:
            best = max(best, match.end())
    if best > 0:
        return best

    # Then a line break, then any whitespace, then a hard character cut.
    newline = window.rfind("\n")
    if newline > 0 and newline >= max_size // 2:
        return newline
    whitespace = max(window.rfind(" "), window.rfind("\t"))
    if whitespace > 0 and whitespace >= max_size // 2:
        return whitespace
    return max(1, min(len(window), max_size))


def _split_oversized(text: str, start: int, end: int,
                     max_size: int) -> Iterator[tuple[int, int]]:
    """Split one oversized paragraph into pieces of at most ``max_size``."""
    position = start
    while position < end:
        limit = min(position + max_size, end)
        if limit < end:
            limit = position + _best_cut(text[position:limit], max_size)
        span = _trimmed_span(text, position, limit)
        if span is not None:
            yield span
        position = limit


def _paragraph_spans(text: str) -> Iterator[tuple[int, int]]:
    """Yield character spans for blank-line-separated paragraphs."""
    for match in _PARAGRAPH_RE.finditer(text):
        span = _trimmed_span(text, match.start(), match.end())
        if span is not None:
            yield span


def by_paragraph(page: DocumentPage, max_size: int) -> list[Chunk]:
    """Group paragraphs, split oversized paragraphs and retain metadata.

    Paragraphs are separated by blank lines. Consecutive paragraphs are packed
    into chunks of at most ``max_size`` characters; a paragraph larger than the
    limit is split at sentence/line/word boundaries first, with a hard cut as
    the last resort, so no returned chunk exceeds the limit.
    """
    if max_size <= 0:
        raise ValueError("max_size must be greater than 0")

    text = page.text or ""
    if not text.strip():
        return []

    pieces: list[tuple[int, int]] = []
    for start, end in _paragraph_spans(text):
        if end - start <= max_size:
            pieces.append((start, end))
        else:
            pieces.extend(_split_oversized(text, start, end, max_size))

    chunks: list[Chunk] = []
    buffer: list[tuple[int, int]] = []
    buffer_length = 0

    def flush() -> None:
        nonlocal buffer, buffer_length
        if not buffer:
            return
        chunk_text = "\n".join(text[start:end] for start, end in buffer)
        chunks.append(
            _make_chunk(
                page,
                "paragraph",
                len(chunks),
                buffer[0][0],
                buffer[-1][1],
                {"chunk_size_limit": max_size},
                text_override=chunk_text,
            )
        )
        buffer = []
        buffer_length = 0

    for start, end in pieces:
        piece_length = end - start
        separator_length = 1 if buffer else 0
        if buffer and buffer_length + separator_length + piece_length > max_size:
            flush()
        buffer.append((start, end))
        if len(buffer) > 1:
            buffer_length += 1
        buffer_length += piece_length
    flush()
    return chunks
